"""Install enemy summary UI after the unified dashboard patch."""
from pathlib import Path
import base64
base=Path(__file__).resolve().parent
data={'static/intel.js': '', 'static/intel.css': '', 'templates/intel.html': ''}
for name, encoded in data.items():
    path=base/name
    if not path.exists():
        raise RuntimeError(f"Dashboard file missing: {name}")
    path.write_bytes(base64.b64decode(encoded))
print("Enemy summary dashboard added")